  0.20, ! C2 {Unitless}
  -8.60, ! C3 {Unitless}
  0.93, ! A0 {Unitless}
  0.05, ! A1 {Unitless}
  -7.9402e-03, ! A2 {Unitless}
  5.2228e-04, ! A3 {Unitless}
  -1.3142e-05, ! A4 {Unitless}
  1.00, ! B0 {Unitless}
  -2.438e-03, ! B1 {Unitless}
  3.103e-04, ! B2 {Unitless}
  -1.246e-05, ! B3 {Unitless}
  2.112e-07, ! B4 {Unitless}
  -1.359e-09, ! B5 {Unitless}
  3.00, ! dT0 {degC}
  1.00, ! fd {Unitless}
  -3.47, ! a {Unitless}
  -0.05, ! b {Unitless}
