      0.0000000E+00,           !- X Origin {m}
      6.096000,                !- Y Origin {m}
      0.0000000E+00,           !- Z Origin {m}
      1,                       !- Type
      1,                       !- Multiplier
      autocalculate,           !-Ceiling Height {m}
      autocalculate;           !- Volume {m3}
</code></pre>

